<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;$error='';$id=(int)($_GET['id']??0);$l=$id?one('SELECT * FROM licenses WHERE id=?',[$id]):null;if($id&&!$l){http_response_code(404);exit('Licença não encontrada.');}$order=isset($_GET['pedido'])?one('SELECT * FROM orders WHERE id=?',[(int)$_GET['pedido']]):null;if(is_post()){verify_csrf();try{$customer=(int)($_POST['user_id']??0);$product=(int)($_POST['product_id']??0);$d=domain(input('domain',253));$expires=input('expires_at',10);$status=input('status',20);if(!one('SELECT id FROM users WHERE id=?',[$customer])||!one('SELECT id FROM products WHERE id=?',[$product])||!in_array($status,['active','suspended'],true))throw new InvalidArgumentException('Cliente, produto ou status inválido.');if($expires!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$expires)||date('Y-m-d',strtotime($expires))!==$expires))throw new InvalidArgumentException('Data inválida.');if(!isset($_POST['verified']))throw new InvalidArgumentException('Confirme a autorização do domínio junto ao cliente antes de liberar.');$key=null;if(!$l||isset($_POST['rotate']))$key='S7V-'.bin2hex(random_bytes(24));$oid=$l['order_id']??null;if(!$l&&input('order_id',20)!==''){$o=one('SELECT * FROM orders WHERE id=?',[(int)$_POST['order_id']]);if(!$o||(int)$o['user_id']!==$customer||(int)$o['product_id']!==$product||!in_array($o['status'],['paid','delivered'],true))throw new InvalidArgumentException('O pedido deve pertencer ao cliente/produto e estar pago ou entregue.');$oid=$o['id'];if(one('SELECT id FROM licenses WHERE order_id=?',[$oid]))throw new InvalidArgumentException('Este pedido já possui licença. Edite a licença existente.');}if($l){run('UPDATE licenses SET user_id=?,product_id=?,domain=?,status=?,expires_at=?,key_hash=? WHERE id=?',[$customer,$product,$d,$status,$expires?:null,$key?hash('sha256',$key):$l['key_hash'],$id]);}else{run('INSERT INTO licenses (user_id,product_id,order_id,domain,key_hash,status,expires_at,created_at) VALUES (?,?,?,?,?,?,?,?)',[$customer,$product,$oid,$d,hash('sha256',$key),$status,$expires?:null,date('Y-m-d H:i:s')]);$id=(int)db()->lastInsertId();}audit('licenca_atualizada','Licença #'.$id.' '.$status.' '.$d);if($key)$_SESSION['issued_key']=$key;flash('Licença salva. Registre a chave exibida para entregá-la ao cliente.');go('admin/licencas.php?id='.$id);}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}
require ROOT.'/includes/panel.php';?><div class="toolbar"><h1>Clientes e licenças.</h1><a class="primary btn" href="<?=e(url('admin/licencas.php?novo=1'))?>">+ Emitir licença</a></div><?php if(isset($_SESSION['issued_key'])):?><div class="notice">Chave completa — copie agora, ela não será exibida novamente:<br><code><?=e($_SESSION['issued_key'])?></code></div><?php unset($_SESSION['issued_key']);endif;if($error):?><div class="errors"><?=e($error)?></div><?php endif;if($l||isset($_GET['novo'])):?><form method="post" data-confirm="Confirmar emissão ou alteração desta licença?"><?php csrf();?><div class="grid-two"><label class="field">Cliente<select name="user_id"><?php foreach(rows('SELECT id,name,email FROM users ORDER BY name') as $c):?><option value="<?=$c['id']?>" <?=(int)($l['user_id']??$order['user_id']??0)===(int)$c['id']?'selected':''?>><?=e($c['name'].' / '.$c['email'])?></option><?php endforeach;?></select></label><label class="field">Produto<select name="product_id"><?php foreach(rows('SELECT id,name FROM products ORDER BY name') as $p):?><option value="<?=$p['id']?>" <?=(int)($l['product_id']??$order['product_id']??0)===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label class="field">Domínio<input name="domain" value="<?=e($l['domain']??$order['domain']??'')?>" required maxlength="253"></label><label class="field">Vencimento (vazio = sem prazo)<input name="expires_at" type="date" value="<?=e($l['expires_at']??'')?>"></label><label class="field">Status<select name="status"><option value="active" <?=($l['status']??'')==='active'?'selected':''?>>Ativa</option><option value="suspended" <?=($l['status']??'')==='suspended'?'selected':''?>>Suspensa</option></select></label><?php if(!$l):?><label class="field">Pedido pago vinculado (opcional)<input type="number" name="order_id" min="1" value="<?=e($order['id']??'')?>"></label><?php endif;?></div><label class="check"><input type="checkbox" name="verified" required>Verifiquei a autorização de uso do domínio com o cliente.</label><?php if($l):?><label class="check"><input type="checkbox" name="rotate">Gerar nova chave e invalidar a anterior.</label><?php endif;?><button class="primary">Salvar licença</button></form><?php else:?><div class="table-wrap"><table><tr><th>Cliente</th><th>Produto / domínio</th><th>Renovação</th><th>Status</th><th>Ação</th></tr><?php foreach(rows('SELECT l.*,u.name customer,p.name product FROM licenses l JOIN users u ON u.id=l.user_id JOIN products p ON p.id=l.product_id ORDER BY l.id DESC LIMIT 300') as $l):?><tr><td><?=e($l['customer'])?></td><td><?=e($l['product'])?><br><?=e($l['domain'])?></td><td><?=e(datebr($l['expires_at']))?></td><td><?=e($l['status'])?></td><td><a href="<?=e(url('admin/licencas.php?id='.$l['id']))?>">Gerenciar ↗</a></td></tr><?php endforeach;?></table></div><?php endif;require ROOT.'/includes/endpanel.php';?>
